               Part.CONTENT_LOCATION + " TEXT," +
               Part.CT_START + " INTEGER," +
               Part.CT_TYPE + " TEXT," +
               Part._DATA + " TEXT," +
               Part.TEXT + " TEXT);");

    db.execSQL("CREATE TABLE " + MmsProvider.TABLE_RATE + " (" +
               Rate.SENT_TIME + " INTEGER);");

    db.execSQL("CREATE TABLE " + MmsProvider.TABLE_DRM + " (" +
               BaseColumns._ID + " INTEGER PRIMARY KEY," +
               "_data TEXT);");
